// Some portions generated by Claude
/** The active filters as pills (filter-panel.tsx): one per selected value, grouped per filter. */
import type { FacetMode, FacetModes } from "./graph-facets.ts";

/** One pill: a selected value of a filter, or a whole range filter (`valueId` null). */
export type FilterChip = { facetId: string; facetLabel: string; valueId: string | null; text: string };

/**
 * The pills of one filter and how its values combine: "or" between the values of a filter that matches any of them,
 * "and" when it needs all of them; no joiner for a single pill. `label` names the group for screen readers.
 */
export type FilterChipGroup = {
  facetId: string;
  mode: FacetMode;
  joiner: "or" | "and" | null;
  label: string;
  chips: FilterChip[];
};

/** The pills grouped per filter, in the order of the filters. */
export function filterChipGroups(chips: readonly FilterChip[], modes: FacetModes): FilterChipGroup[] {
  const groups: FilterChipGroup[] = [];
  const byFacet = new Map<string, FilterChipGroup>();
  for (const chip of chips) {
    let group = byFacet.get(chip.facetId);
    if (!group) {
      const mode = modes.get(chip.facetId) === "all" ? "all" : "any";
      group = { facetId: chip.facetId, mode, joiner: null, label: chip.facetLabel, chips: [] };
      byFacet.set(chip.facetId, group);
      groups.push(group);
    }
    group.chips.push(chip);
  }
  for (const group of groups) {
    if (group.chips.length < 2) continue;
    group.joiner = group.mode === "all" ? "and" : "or";
    group.label = `${group.label}, ${group.mode === "all" ? "all" : "any"} of`;
  }
  return groups;
}
